"""Anatomical descriptions of every MOSSlight fish. One entry per species; no shared body."""
from .fish import *
SPECIES = {}
def F(id, L, top, bot, back, flank, belly, fin, behind=(), over=(), last=(), spine=None, **k):
    SPECIES[id] = dict(id=id, L=L, arch=k.get('arch', 0), spine=spine or straight(L, k.pop('arch', 0)), fit=spine is None, top=top, bot=bot, back=back, flank=flank, belly=belly, fin=fin, behind=list(behind), over=list(over), last=list(last), **k)
fin = lambda *a, **k: (lambda p: p.fin(*a, **k))
tail = lambda *a, **k: (lambda p: p.tail(*a, **k))
pad = lambda *a, **k: (lambda p: p.paddle(*a, **k))
barb = lambda *a, **k: (lambda p: p.barbel(*a, **k))
E = lambda t, v, r=1, **k: dict(t=t, v=v, r=r, **k)

